const result = presentation.help('*', {
  search: 'slide.shapes.delete|shape.delete|slide.shapes.add|deleteAll',
  include: ['index', 'examples', 'notes'],
  maxChars: 12000,
});
console.log(result.ndjson);

const slide = presentation.slides.add();
const { patch } = presentation.record(() => {
  const shape = slide.shapes.add({ geometry: 'rect' });
  shape.text = 'Hello';
});
console.log(patch);

presentation.comments.setSelf({ displayName: 'Granola Bot', initials: 'GB' });
const slide = presentation.slides.add();
const shape = slide.shapes.add({ geometry: 'rect' });
presentation.comments.addThread({ element: shape }, 'Review this copy');

const cards = [
  slide.shapes.add({ geometry: 'rect' }),
  slide.shapes.add({ geometry: 'rect' }),
];
slide.autoLayout(cards, { direction: 'vertical', align: 'center', verticalGap: 16 });

const shape = slide.shapes.add({
  geometry: 'roundRect',
  position: { left: 72, top: 96, width: 320, height: 120 },
  fill: { type: 'solid', color: 'accent1' },
  line: { style: 'solid', fill: 'accent2', width: 2 },
});
shape.text = 'Launch plan';

const from = slide.shapes.add({ geometry: 'rect', position: { left: 40, top: 80, width: 120, height: 60 } });
const to = slide.shapes.add({ geometry: 'ellipse', position: { left: 280, top: 120, width: 120, height: 60 } });
slide.shapes.connect(from, to, {
  kind: 'elbow',
  fromSide: 'right',
  toSide: 'left',
  line: { style: 'solid', fill: 'accent1', width: 2 },
});

const shape = slide.shapes.add({ geometry: 'rect' });
shape.name = 'Headline';
const byName = slide.shapes.getItem('Headline');
const byId = slide.shapes.getItem({ id: shape.id });
console.log(byName?.id, byId?.name);
